using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;

namespace MapSharedProps.EditorTools {
// Optional editor-mesh sidecar. Old exports without it retain the previous importer behavior.
public static class SmallPropsV1 {
 [Serializable] public class Asset {public string id,assetKey,source,material;public float radius,height,groundSink;public bool shape;public float[] light,positions,normals,colors,glow,uv;public int[] triangles;public GroundedPropsV1.Part[] parts;}
 [Serializable] public class Tint {public string instanceId;public float[] tint;}
 [Serializable] public class Atlas {public int width,height;public string png,colorSpace,filter,wrap;public bool mipmaps;}
 [Serializable] public class Data {public Atlas atlas;public Tint[] instances;public int version;public string units,axes;public Asset[] assets;public GroundedPropsV1.Data grounded;}
 public static readonly HashSet<string> Ids=new HashSet<string>(new[]{"bones","bonepile","skullpile","statue","statue_seated","statue_damaged","stele","gravestone","brokencol","brokencol_base","columnfragment","lantern","miningtools","supplycrate","smallbarrel","tiedsack","coiledrope","storagepot","brokenpot"});
 static void Check(bool ok,string why){if(!ok)throw new InvalidDataException("Small props: "+why);}
 static bool Finite(float f){return !float.IsNaN(f)&&!float.IsInfinity(f);}
 static void Floats(float[] a,int n){Check(a!=null&&a.Length==n,"array length");foreach(float f in a)Check(Finite(f),"nonfinite value");}
 static Vector3 V(float[] a){Floats(a,3);return new Vector3(a[0],a[1],a[2]);}
 static float Number(string s){float f=float.Parse(s,CultureInfo.InvariantCulture);Check(Finite(f),"CSV nonfinite");return f;}
 public static Data Read(string file){var d=JsonUtility.FromJson<Data>(File.ReadAllText(file));Check(d!=null&&d.version==1&&d.units=="metres"&&d.axes=="Unity X/Y/Z"&&d.assets!=null&&d.assets.Length==Ids.Count,"format/count");var found=new HashSet<string>();foreach(var a in d.assets){Check(a!=null&&Ids.Contains(a.id)&&found.Add(a.id)&&a.assetKey=="tdj/"+a.id&&a.source=="editor-procedural-mesh","identity");Check(a.positions!=null&&a.positions.Length>0&&a.positions.Length%3==0&&a.positions.Length<180000,"mesh count");int n=a.positions.Length/3;Floats(a.positions,n*3);Floats(a.normals,n*3);Floats(a.colors,n*3);Floats(a.glow,n);Floats(a.uv,n*2);Check(a.triangles!=null&&a.triangles.Length%3==0,"triangles");foreach(int ix in a.triangles)Check(ix>=0&&ix<n,"index");Check(Finite(a.radius)&&a.radius>=0&&Finite(a.height)&&a.height>0,"collision metadata");Check(a.material=="default"||a.material=="stone"||a.material=="carved"||a.material=="cards2","material");foreach(float g in a.glow)Check(g>=0&&g<=4,"glow");}return d;}
 public static Mesh MeshOf(float[] p,float[] normal,float[] color,int[] ix,float[] glow=null){int n=p.Length/3;Floats(p,n*3);Floats(normal,n*3);Floats(color,n*3);var v=new Vector3[n];var nn=new Vector3[n];var cc=new Color[n];var gg=new List<Vector2>(n);for(int k=0;k<n;k++){v[k]=new Vector3(p[k*3],p[k*3+1],p[k*3+2]);nn[k]=new Vector3(normal[k*3],normal[k*3+1],normal[k*3+2]);cc[k]=new Color(color[k*3],color[k*3+1],color[k*3+2],1);gg.Add(new Vector2(glow==null?0:glow[k],0));}var m=new Mesh{indexFormat=n>65535?IndexFormat.UInt32:IndexFormat.UInt16,vertices=v,normals=nn,colors=cc,uv=new Vector2[n],triangles=ix};m.SetUVs(2,gg);m.RecalculateBounds();return m;}
 static void Collider(GameObject o,Asset a,Mesh source){if(a.radius<=0)return;var c=o.AddComponent<MeshCollider>();if(a.shape){c.sharedMesh=source;return;}const int N=24;var v=new List<Vector3>();for(int y=0;y<2;y++)for(int j=0;j<N;j++){float t=j*Mathf.PI*2/N;v.Add(new Vector3(Mathf.Cos(t)*a.radius,y*a.height,Mathf.Sin(t)*a.radius));}v.Add(Vector3.zero);v.Add(Vector3.up*a.height);var ix=new List<int>();for(int j=0;j<N;j++){int k=(j+1)%N;ix.AddRange(new[]{j,j+N,k,k,j+N,k+N,2*N,k,j,2*N+1,j+N,k+N});}var mesh=new Mesh{name=a.id+"-circle-proxy",vertices=v.ToArray(),triangles=ix.ToArray()};mesh.RecalculateBounds();c.sharedMesh=mesh;}
 public static int Build(string directory,string assetDirectory,Transform parent,Shader shader,Dictionary<string,GameObject> prefabs){string file=Path.Combine(directory,"small_props.json");if(!File.Exists(file))return 0;var data=Read(file);Check(data.atlas!=null&&data.atlas.colorSpace=="sRGB"&&data.atlas.width>0&&data.atlas.width<=1024&&data.atlas.height>0&&data.atlas.height<=1024,"atlas contract");var atlas=new Texture2D(2,2,TextureFormat.RGBA32,true,false){name="small-props-existing-wood-atlas",wrapMode=TextureWrapMode.Clamp,filterMode=FilterMode.Trilinear,anisoLevel=2};Check(ImageConversion.LoadImage(atlas,Convert.FromBase64String(data.atlas.png)),"atlas PNG");Check(atlas.width==data.atlas.width&&atlas.height==data.atlas.height,"atlas size");AssetDatabase.CreateAsset(atlas,assetDirectory+"/small-existing-atlas.asset");var assets=new Dictionary<string,Asset>();var mats=new Dictionary<string,Material>();
  foreach(var a in data.assets){assets.Add(a.id,a);string key=a.material+(Array.Exists(a.glow,g=>g>0)?"-glow":"");if(!mats.ContainsKey(key)){var mat=new Material(shader){name="small-props-"+key};mat.SetTexture("_BaseMap",a.material=="cards2"?atlas:Texture2D.whiteTexture);mat.SetColor("_BaseColor",Color.white);mat.SetFloat("_Cutoff",a.material=="cards2"?.42f:0);mat.SetFloat("_Cull",2);if(key.EndsWith("-glow"))mat.EnableKeyword("SHARED_GLOW");AssetDatabase.CreateAsset(mat,assetDirectory+"/small-"+key+".mat");mats.Add(key,mat);}var mesh=MeshOf(a.positions,a.normals,a.colors,a.triangles,a.glow);var uv=new Vector2[a.uv.Length/2];for(int k=0;k<uv.Length;k++)uv[k]=new Vector2(a.uv[k*2],a.material=="cards2"?1-a.uv[k*2+1]:a.uv[k*2+1]);mesh.uv=uv;mesh.name=a.id;AssetDatabase.CreateAsset(mesh,assetDirectory+"/small-"+a.id+".asset");var o=new GameObject(a.id);o.AddComponent<MeshFilter>().sharedMesh=mesh;var r=o.AddComponent<MeshRenderer>();r.sharedMaterial=mats[key];r.shadowCastingMode=ShadowCastingMode.On;r.receiveShadows=true;Collider(o,a,mesh);if(a.light!=null&&a.light.Length==3){var light=new GameObject("Light").AddComponent<Light>();light.transform.SetParent(o.transform,false);light.transform.localPosition=new Vector3(0,a.height*.9f,0);light.type=LightType.Point;int color=(int)a.light[0];light.color=new Color32((byte)(color>>16),(byte)(color>>8),(byte)color,255);light.intensity=a.light[1];light.range=a.light[2];light.shadows=LightShadows.None;}var path=assetDirectory+"/small-"+a.id+".prefab";prefabs.Add(a.id,PrefabUtility.SaveAsPrefabAsset(o,path));UnityEngine.Object.DestroyImmediate(o);}
  var ground=new Dictionary<string,GroundedPropsV1.Instance>();if(data.grounded!=null&&data.grounded.instances!=null)foreach(var g in data.grounded.instances){Check(g!=null&&Ids.Contains(g.type)&&!ground.ContainsKey(g.instanceId),"ground identity");ground.Add(g.instanceId,g);}
  var tints=new Dictionary<string,float[]>();if(data.instances!=null)foreach(var t in data.instances){Floats(t.tint,3);Check(!tints.ContainsKey(t.instanceId),"duplicate tint");tints.Add(t.instanceId,t.tint);}
  int placed=0;foreach(string line in File.ReadAllLines(Path.Combine(directory,"props.csv"))){var row=line.Split(',');if(row.Length!=11||!assets.TryGetValue(row[1],out var a))continue;Check(row[2]==a.assetKey,"CSV asset key");var o=(GameObject)PrefabUtility.InstantiatePrefab(prefabs[a.id],parent);o.name=row[0];o.transform.localPosition=new Vector3(Number(row[3]),Number(row[4]),Number(row[5]));o.transform.localRotation=Quaternion.Euler(0,Number(row[6]),0);o.transform.localScale=new Vector3(Number(row[7]),Number(row[8]),Number(row[7]));Check(o.transform.localScale.x>0&&o.transform.localScale.y>0,"scale");
   if(ground.TryGetValue(row[0],out var pose)){Check(a.parts!=null&&pose.parts!=null&&a.parts.Length==pose.parts.Length,"ground parts");for(int k=0;k<3;k++)Check(Mathf.Abs(o.transform.localPosition[k]-pose.source.position[k])<.0011f,"ground source position");Check(Mathf.Abs(Number(row[6])-pose.source.yaw)<.011f,"ground source rotation");var pieces=new CombineInstance[a.parts.Length];var temporary=new List<Mesh>();for(int k=0;k<a.parts.Length;k++){var part=a.parts[k];var tr=Array.Find(pose.parts,p=>p.id==part.id);Check(tr!=null,"ground part identity");Floats(tr.rotation,4);var mesh=MeshOf(part.positions,part.normals,part.colors,part.triangles);temporary.Add(mesh);pieces[k]=new CombineInstance{mesh=mesh,transform=Matrix4x4.TRS(o.transform.localPosition,o.transform.localRotation,o.transform.localScale).inverse*Matrix4x4.TRS(V(tr.position),new Quaternion(tr.rotation[0],tr.rotation[1],tr.rotation[2],tr.rotation[3]),V(tr.scale))};}var combined=new Mesh{name=a.id+"-grounded"};combined.CombineMeshes(pieces,true,true);combined.RecalculateBounds();AssetDatabase.CreateAsset(combined,assetDirectory+"/small-grounded-"+placed.ToString("D4")+".asset");o.GetComponent<MeshFilter>().sharedMesh=combined;foreach(var mesh in temporary)UnityEngine.Object.DestroyImmediate(mesh);}
   if(tints.TryGetValue(row[0],out var tint)){var block=new MaterialPropertyBlock();block.SetColor("_BaseColor",new Color(tint[0],tint[1],tint[2],1));o.GetComponent<Renderer>().SetPropertyBlock(block);}
   placed++;
  }return placed;
 }
}
}
